import {expect, it} from '@jest/globals';
import {ToolRegistry} from './registry.js';

it('passes valid location and extra properties unchanged exactly once', async () => {
  const registry = new ToolRegistry();
  const inputs: Record<string, unknown>[] = [];
  const input = {location: 'Berlin', extra: 42};
  registry.register(
    {
      name: 'weather',
      description: 'Weather forecast',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}, units: {type: 'string', default: 'celsius'}},
        required: ['location'],
      },
    },
    async received => {
      inputs.push(received);
      return 'forecast';
    }
  );

  const response = await registry.execute('weather', input);

  expect({response, inputs}).toEqual({response: {result: 'forecast'}, inputs: [input]});
});
''')
